import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                res = res * 10 + c - '0';
                c = read();
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);
        int n = in.nextInt();
        if (n == -1) return;
        int k = in.nextInt();

        // Máxima soma possível é 500.000 * 100 = 50.000.000
        int[] freq = new int[50000005];
        freq[0] = 1;

        long count = 0;
        int currentSum = 0;

        for (int i = 0; i < n; i++) {
            int x = in.nextInt();
            currentSum += x;
            if (currentSum >= k) {
                count += freq[currentSum - k];
            }
            freq[currentSum]++;
        }

        System.out.println(count);
    }
}
